effects.bounds:
let reach = (abs(distance) + abs(softness)) * raster_scale;
left = x0 - reach;
top = y0 - reach;
right = x1 + reach;
bottom = y1 + reach;

let reach = (abs(separation) + abs(slide)) * raster_scale;
left = x0 - reach;
top = y0 - reach;
right = x1 + reach;
bottom = y1 + reach;

shader.source:
let mid = (left + right) * 0.5;
let side = (left - right) * 0.5 * width;
out = select(channels < 2, in, select(channel == 0, mid + side, mid - side));
